import React from "react";
import { motion } from "framer-motion";
import Header from "./Header";
import profile from "../assets/profile.jpg";

const Hero = () => {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.15,
        delayChildren: 0.2,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.6, ease: "easeOut" },
    },
  };

  const profileVariants = {
    hidden: { opacity: 0, scale: 0.8 },
    visible: {
      opacity: 1,
      scale: 1,
      transition: { duration: 0.8, ease: "easeOut" },
    },
  };

  return (
    <motion.section
      className="hero"
      id="top"
      variants={containerVariants}
      initial="hidden"
      animate="visible"
    >
      <motion.div className="hero-card" variants={itemVariants}>
        <Header isInCard={true} />

        <div className="hero-card-body">
          <motion.div className="hero-card-left" variants={itemVariants}>
            <motion.p className="hero-greeting" variants={itemVariants}>
              Hello,
            </motion.p>

            <motion.h1 variants={itemVariants}>
              This is <br /> <strong>Mallikarjun Bendawade.</strong>
            </motion.h1>

            <motion.p className="hero-subtitle" variants={itemVariants}>
              AI & Software Developer <br /> from Bengaluru
            </motion.p>

            <motion.div className="hero-badges" variants={itemVariants}>
              <span className="badge">
                <span className="dot"></span>Trusted
              </span>
              <span className="badge">
                <span className="dot"></span>Result Oriented
              </span>
              <span className="badge">
                <span className="dot"></span>Next Level Expert
              </span>
            </motion.div>

            <motion.div className="hero-cta" variants={itemVariants}>
              <motion.a
                href="#contact"
                className="btn btn-primary"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                Hire me
              </motion.a>
              <motion.a
                href="#projects"
                className="btn btn-secondary"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                See My Works
              </motion.a>
            </motion.div>
          </motion.div>

          <motion.div className="hero-card-right" variants={profileVariants}>
            <motion.div className="profile-circle">
              <img src={profile} alt="Mallikarjun Bendawade" />
            </motion.div>
          </motion.div>
        </div>
      </motion.div>

      <motion.div className="hero-scroll" variants={itemVariants}>
        <motion.div
          className="scroll-indicator"
          animate={{ y: [0, 10, 0] }}
          transition={{ duration: 2, repeat: Infinity }}
        >
          ↓
        </motion.div>
      </motion.div>
    </motion.section>
  );
};

export default Hero;
